<?php require_once __DIR__.'/../includes/layout.php';$u=require_role('admin');if($_SERVER['REQUEST_METHOD']==='POST'){check_csrf();$id=(int)($_POST['id']??0);$active=(int)($_POST['active']??0);if($id!==user_id())db()->prepare('UPDATE usuarios SET activo=? WHERE id=? AND rol!="admin"')->execute([$active?1:0,$id]);flash('success','Estado de usuario actualizado.');go('admin/usuarios.php');}$users=all('SELECT u.id,u.nombre,u.apellido_paterno,u.correo,u.rol,u.activo FROM usuarios u ORDER BY u.id DESC LIMIT 200');header_ui('Usuarios');?><div class="page-intro"><h2>Gestión de usuarios 👥</h2><p>Consulta las cuentas y activa o desactiva su acceso.</p></div><div class="panel"><div class="table-wrap"><table><thead><tr><th>Nombre</th><th>Correo</th><th>Perfil</th><th>Estado</th><th></th></tr></thead><tbody><?php foreach($users as $r):?><tr><td><?=e($r['nombre'].' '.$r['apellido_paterno'])?></td><td><?=e($r['correo'])?></td><td><?=e(ucfirst($r['rol']))?></td><td><span class="badge <?=$r['activo']?'badge-mint':'badge-muted'?>"><?=$r['activo']?'Activo':'Inactivo'?></span></td><td><?php if($r['rol']!=='admin'):?><form method="post"><input type="hidden" name="csrf" value="<?=csrf()?>"><input type="hidden" name="id" value="<?=$r['id']?>"><input type="hidden" name="active" value="<?=$r['activo']?0:1?>"><button class="btn btn-sm btn-ghost"><?=$r['activo']?'Desactivar':'Activar'?></button></form><?php endif;?></td></tr><?php endforeach;?></tbody></table></div></div><?php footer_ui();?>
